def ee(name, quote_name=None, rank='ladder', title='Professor', emeritus=False, note=None, diss=None, period=None, also=None, home_last=False):
    """An EECS EE-division faculty member: the live EE faculty list names them; EECS lists give the years; an EECS dissertation gives PI status."""
    q = quote_name or name
    return dict(home=EEH, also=also or [], rank=rank, title=title, eecs=[q],
                listings=[], home_evidence=('last_eecs',) if home_last else ('ee_list', q), pi=('diss', diss) if diss else ('diss_auto', None), period=period, note=note)


